<dialog id="notification-detail-modal" aria-label="Notification Detail" class="m-auto max-h-[85vh] w-[calc(100%-2rem)] max-w-2xl overflow-y-auto rounded-2xl border border-slate-700 bg-slate-900 p-5 text-white shadow-2xl backdrop:bg-black/70 sm:p-6">
    <div class="mb-4 flex justify-end"><button type="button" data-close-notification class="rounded-lg px-3 py-2 text-sm text-slate-300 hover:bg-slate-800" autofocus>Close</button></div>
    <div id="notification-detail-content" aria-live="polite"></div>
</dialog>
